/**
 * NER-LOGIX SIMULATION DATA.
 *
 * Everything in this file is generated by the NER-LOGIX prototype for
 * demonstration. It is NOT government data and is labelled as simulation
 * everywhere it is rendered. Later steps replace it with live system data.
 *
 * Positions reference real district label points so simulated items land in the
 * correct place on the real map.
 */

import { getDistrictCentroid } from "@/services/government/lgdService";
import type {
  Incident,
  OperationalAlert,
  RouteSegment,
  TransportMission,
  Vehicle,
} from "@/types/domain";

/** Offset a district label point slightly so multiple markers stay readable. */
function near(districtId: string, dLng = 0, dLat = 0): [number, number] {
  const c = getDistrictCentroid(districtId);
  if (!c) return [0, 0];
  return [c[0] + dLng, c[1] + dLat];
}

