export function incidentsForDistrict(districtId: string): Incident[] {
  return SIM_INCIDENTS.filter((i) => i.districtId === districtId);
}

export function missionsForDistrict(districtId: string): TransportMission[] {
  return SIM_MISSIONS.filter(
    (m) => m.originDistrictId === districtId || m.destinationDistrictId === districtId,
  );
}

export function routeLine(route: RouteSegment): [number, number][] {
  return route.waypointDistrictIds
    .map((id) => getDistrictCentroid(id))
    .filter((c): c is [number, number] => Boolean(c))
    .map(([lng, lat]) => [lat, lng] as [number, number]);
}
